import numpy as np
from scipy.ndimage import distance_transform_edt,gaussian_filter1d

def boundaries(m):
 # Trace directed grid edges with occupied pixels on the right.
 ys,xs=np.nonzero(m);edges={}
 for y,x in zip(ys,xs):
  if y==0 or not m[y-1,x]:edges[(x,y)]=(x+1,y)
  if x==m.shape[1]-1 or not m[y,x+1]:edges[(x+1,y)]=(x+1,y+1)
  if y==m.shape[0]-1 or not m[y+1,x]:edges[(x+1,y+1)]=(x,y+1)
  if x==0 or not m[y,x-1]:edges[(x,y+1)]=(x,y)
 loops=[]
 while edges:
  start=next(iter(edges));cur=start;path=[]
  while cur in edges:
   path.append(cur);cur=edges.pop(cur)
   if cur==start:break
  if len(path)>8:
   p=np.array(path,dtype=float)-.5
   p=gaussian_filter1d(p,1.5,axis=0,mode='wrap')
   p=np.vstack([p,p[0]]);ds=np.r_[0,np.cumsum(np.linalg.norm(np.diff(p,axis=0),axis=1))]
   n=max(6,int(np.ceil(ds[-1]/1.7)))
   t=np.linspace(0,ds[-1],n+1)
   loops.append(np.stack([np.interp(t,ds,p[:,k]) for k in range(2)],axis=1))
 return sorted(loops,key=len,reverse=True)

def loops_for(m,margin=3.6,spacing=5.2):
 d=distance_transform_edt(m);out=[]
 for a in np.arange(margin,d.max(),spacing):
  for loop in boundaries(d>a):out.append(loop)
 return out
